class Solution:
    def countZeroQuads(self, a: List[int], b: List[int], c: List[int], d: List[int]) -> int:
        total = 0
        for w in a:
            for x in b:
                for y in c:
                    for z in d:
                        if w + x + y + z == 0:
                            total += 1
        return total

