static int cmpInt(const void* x, const void* y) {
    int p = *(const int*) x, q = *(const int*) y;
    return (p > q) - (p < q);
}

// How many times v appears in the sorted array s of length n.
static int occurrences(const int* s, int n, int v) {
    int lo = 0, hi = n;
    while (lo < hi) {
        int mid = (lo + hi) / 2;
        if (s[mid] < v) lo = mid + 1; else hi = mid;
    }
    int first = lo;
    hi = n;
    while (lo < hi) {
        int mid = (lo + hi) / 2;
        if (s[mid] <= v) lo = mid + 1; else hi = mid;
    }
    return lo - first;
}

long long countZeroQuads(int* a, int aSize, int* b, int bSize, int* c, int cSize, int* d, int dSize) {
    int* sortedD = malloc(dSize * sizeof(int));
    memcpy(sortedD, d, dSize * sizeof(int));
    qsort(sortedD, dSize, sizeof(int), cmpInt);
    long long total = 0;
    for (int i = 0; i < aSize; i++)
        for (int j = 0; j < bSize; j++)
            for (int k = 0; k < cSize; k++)
                total += occurrences(sortedD, dSize, -(a[i] + b[j] + c[k]));
    free(sortedD);
    return total;
}

