class Solution {
public:
    long long countZeroQuads(vector<int>& a, vector<int>& b, vector<int>& c, vector<int>& d) {
        unordered_map<int, int> sums;
        sums.reserve(a.size() * b.size() * 2);
        for (int w : a)
            for (int x : b)
                sums[w + x]++;
        long long total = 0;
        for (int y : c)
            for (int z : d) {
                auto it = sums.find(-(y + z));
                if (it != sums.end()) total += it->second;
            }
        return total;
    }
};

