// A small hash map from a sum to its count: open addressing, linear probing.
typedef struct { int key; int count; bool used; } Slot;

static unsigned slotOf(int key, unsigned mask) {
    unsigned long long h = (unsigned long long) (long long) key * 0x9E3779B97F4A7C15ULL;
    return (unsigned) (h >> 32) & mask;
}

static Slot* find(Slot* t, unsigned mask, int key) {
    unsigned s = slotOf(key, mask);
    while (t[s].used && t[s].key != key) s = (s + 1) & mask;
    return &t[s];
}

long long countZeroQuads(int* a, int aSize, int* b, int bSize, int* c, int cSize, int* d, int dSize) {
    unsigned cap = 1;
    while (cap < 2u * aSize * bSize) cap <<= 1;
    Slot* sums = calloc(cap, sizeof(Slot));
    for (int i = 0; i < aSize; i++)
        for (int j = 0; j < bSize; j++) {
            Slot* e = find(sums, cap - 1, a[i] + b[j]);
            e->key = a[i] + b[j];
            e->used = true;
            e->count++;
        }
    long long total = 0;
    for (int k = 0; k < cSize; k++)
        for (int l = 0; l < dSize; l++) {
            Slot* e = find(sums, cap - 1, -(c[k] + d[l]));
            if (e->used) total += e->count;
        }
    free(sums);
    return total;
}
